import escapeZpl from './escapeZpl';

/**
 * Generate ZPL code for a dispatch pallet label
 *
 * Designed for 4" x 6" (100mm x 150mm) direct thermal labels on Zebra ZD421 printer.
 * Used to label physical pallets being loaded onto trucks: who it goes to, the
 * batch, a blank "PALLET ___ OF ___" box for the operator to fill in by hand,
 * and the orders on the batch. No case count: a batch spread over several
 * pallets made the batch total read as this pallet's count.
 *
 * @example
 *   generateDispatchLabelZpl({
 *     batchNumber: 'BATCH-2026-0042',
 *     distributorName: 'MMI Distribution',
 *     orderNumbers: ['SO-00145', 'SO-00146', 'PCO-0023'],
 *     dispatchedAt: new Date(),
 *     notes: 'Truck #42',
 *   });
 */

export interface DispatchLabelData {
  /** Batch number (e.g. BATCH-2026-0042) */
  batchNumber: string;
  /** Distributor / recipient name */
  distributorName: string;
  /** Order numbers included in the batch */
  orderNumbers: string[];
  /** Date dispatched */
  dispatchedAt: Date;
  /** Optional notes (e.g. truck number) */
  notes?: string | null;
}

/**
 * Truncate string to max length with ellipsis
 */
const truncate = (str: string, maxLen: number) => {
  if (str.length <= maxLen) return str;
  return str.slice(0, maxLen - 3) + '...';
};

/**
 * Format date as DD MMM YYYY (e.g. 09 Nov 2026), read the same way by everyone on the dock
 */
const formatDate = (date: Date) =>
  new Date(date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Dubai' });

/** C&C logo as ZPL graphic (400x119 dots, fresh conversion from cc-logo-cropped.png) */
const DISPATCH_LOGO_GF = '^GFA,5950,5950,50,';

/** Width of the printable area between the side margins */
const CONTENT_WIDTH = 712;

/** Order rows on the label, two orders a row; one row fewer when there are notes */
const ORDER_ROWS = 5;
const ORDER_ROW_HEIGHT = 44;

/**
 * Generate ZPL code for a dispatch pallet label
 *
 * Label layout (4" x 6" at 203 DPI = 812 x 1218 dots):
 * - Top: C&C logo (left), dispatch date (right)
 * - DELIVER TO: distributor name, large, up to two lines
 * - Batch number
 * - Boxed PALLET ___ OF ___ for hand-writing
 * - Orders in two columns, "+N more" when they do not fit
 * - Notes
 * - Website footer
 */
const generateDispatchLabelZpl = (data: DispatchLabelData) => {
  const batchNumber = escapeZpl(data.batchNumber);
  const distributorName = escapeZpl(truncate(data.distributorName, 50));
  const dispatchDate = escapeZpl(formatDate(data.dispatchedAt));
  const notesText = data.notes ? escapeZpl(truncate(data.notes, 90)) : '';

  // Orders fill two columns; when they overflow, the last slot says how many more
  const rows = notesText ? ORDER_ROWS - 1 : ORDER_ROWS;
  const slots = rows * 2;
  const overflow = data.orderNumbers.length > slots;
  const shown = overflow ? data.orderNumbers.slice(0, slots - 1) : data.orderNumbers;
  const entries = [
    ...shown.map((order) => escapeZpl(truncate(order, 24))),
    ...(overflow ? [`+${data.orderNumbers.length - shown.length} more`] : []),
  ];

  const ORDER_START_Y = 875;
  const orderLines = entries
    .map((text, i) => {
      const x = i % 2 === 0 ? 50 : 420;
      const y = ORDER_START_Y + Math.floor(i / 2) * ORDER_ROW_HEIGHT;
      return `^FO${x},${y}
^A0N,32,28
^FB350,1,0,L
^FD${text}^FS`;
    })
    .join('\n');

  const ordersEndY = ORDER_START_Y + Math.max(1, Math.ceil(entries.length / 2)) * ORDER_ROW_HEIGHT;
  const notesY = ordersEndY + 15;

  const zpl = `^XA
^PW812
^LL1218
^PR3
~SD20

^FX -- C&C logo (400x119 dots, top-left) --
^FO50,30
${DISPATCH_LOGO_GF}^FS

^FX -- Dispatch date (top-right) --
^FO462,50
^A0N,26,26
^FB300,1,0,R
^FDDISPATCHED^FS
^FO462,88
^A0N,42,42
^FB300,1,0,R
^FD${dispatchDate}^FS

^FO30,175
^GB752,6,6^FS

^FX -- Deliver to --
^FO50,205
^A0N,28,28
^FDDELIVER TO^FS
^FO50,250
^A0N,76,70
^FB${CONTENT_WIDTH},2,8,L
^FD${distributorName}^FS

^FO30,430
^GB752,3,3^FS

^FX -- Batch number --
^FO50,455
^A0N,28,28
^FDBATCH^FS
^FO50,495
^A0N,60,56
^FD${batchNumber}^FS

^FX -- Pallet box (hand-write) --
^FO30,590
^GB752,170,5^FS
^FO30,640
^A0N,80,72
^FB752,1,0,C
^FDPALLET ____ OF ____^FS

^FX -- Orders --
^FO50,795
^A0N,30,30
^FDORDERS (${data.orderNumbers.length})^FS
^FO50,840
^GB${CONTENT_WIDTH},2,2^FS
${orderLines}

${notesText ? `^FX -- Notes --
^FO50,${notesY}
^A0N,30,28
^FB${CONTENT_WIDTH},2,6,L
^FDNotes: ${notesText}^FS
` : ''}
^FX -- Footer --
^FO30,1150
^GB752,2,2^FS
^FO30,1168
^A0N,24,24
^FB752,1,0,C
^FDcraftculture.xyz^FS

^XZ`;

  return zpl;
};

export default generateDispatchLabelZpl;
